(()=>{const out={},e=document.createElement('div');document.body.append(e);for(const writing of ['horizontal-tb','vertical-rl','vertical-lr'])for(const direction of ['ltr','rtl']){e.style.cssText='width:120px;height:60px;padding:1px 2px 3px 4px;margin:5px 6px 7px 8px;writing-mode:'+writing+';direction:'+direction;const s=getComputedStyle(e);out[writing+direction]=Object.fromEntries(['inline-size','block-size','margin-inline-start','margin-inline-end','margin-block-start','margin-block-end','padding-inline-start','padding-inline-end','padding-block-start','padding-block-end'].map(k=>[k,s.getPropertyValue(k)]))}const p=document.createElement('div');document.body.append(p);p.append(e);p.style.cssText='color:rgb(7,8,9);font-size:20px;font-family:monospace;line-height:150%;letter-spacing:.5em';e.style.cssText='color:rgb(1,2,3);font-size:24px;line-height:1.5;letter-spacing:.5em;text-emphasis-color:currentcolor';out.inherited=Object.fromEntries(['font-family','font-size','line-height','letter-spacing','text-emphasis-color','caret-color'].map(k=>[k,getComputedStyle(e).getPropertyValue(k)]));e.style.cssText='font-size:24px';out.inheritedLengths=[getComputedStyle(e).fontFamily,getComputedStyle(e).lineHeight,getComputedStyle(e).letterSpacing];e.style.cssText='display:none;width:25%;height:3em';out.none=[getComputedStyle(e).width,getComputedStyle(e).height];p.remove();return out})()